// Laminar: the parent owns a Var; children receive values, not an ambient scope
val selected = Var(Option.empty[String])

def select(options: Seq[String]): HtmlElement =
  div(options.map(v => li(
    cls := "option",
    onClick --> (_ => selected.set(Some(v))),
    child.text <-- selected.signal.map(s => if s.contains(v) then "selected" else ""),
    v
  )))
